class Spell {
    #manaCost;
    constructor(name, manaCost) {
        this.name = name;
        this.#manaCost = manaCost;
    }
    getManaCost() {
        return this.#manaCost;
    }
    cast() {
        return `${this.name} spell unleashed!`;
    }
}

class FrostboltSpell extends Spell {
    constructor() {
        super("Frostbolt", 15);
    }
    cast() {
        return `A chilling ${this.name} strikes!`;
    }
}

class Wizard {
    #currentMana;
    constructor(name, initialMana) {
        this.name = name;
        this.#currentMana = initialMana;
    }
    getMana() {
        return this.#currentMana;
    }

    castSpell(spell) {
        if (this.#currentMana >= spell.getManaCost()) {
            this.#currentMana -= spell.getManaCost();
            return `${this.name} casts ${spell.name}! ${spell.cast()}`;
        } else {
            return `${this.name} doesn't have enough mana for ${spell.name}! Mana needed: ${spell.getManaCost()}, available: ${this.#currentMana}.`;
        }
    }
}

